      default: "400",
      description: "Amount of curve in the text path"
    },
    {
      name: "direction",
      type: '"left" | "right"',
      default: '"left"',
      description: "Initial direction of the marquee animation"
    },
    {
      name: "interactive",
      type: "boolean",
      default: "true",
