                setSpeed(val);
                forceRerender();
              }}
            />

            <PreviewSlider
              title="Iterations"
              min={1}
              max={50}
              step={1}
              value={maxIterations}
              onChange={(val) => {
                setMaxIterations(val);
                forceRerender();
              }}
            />
          </Flex>
        </Customize>

        <PropTable data={propData} />
        <Dependencies dependencyList={["framer-motion"]} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={decryptedText} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...decryptedText} />
      </CliTab>
    </TabbedLayout>
  );
};

export default DecryptedTextDemo;

