        <Customize>
          <PreviewInput
            title="Scramble Characters"
            value={scrambleChars}
            placeholder="Enter text..."
            maxLength={5}
            width={50}
            onChange={setScrambleChars}
          />

          <PreviewSlider
            title="Radius"
            min={10}
            max={300}
            step={10}
            value={radius}
            onChange={(val) => setRadius(val)}
          />
          <PreviewSlider
            title="Duration"
            min={0.1}
            max={5}
            step={0.1}
            value={duration}
            onChange={(val) => setDuration(val)}
          />
          <PreviewSlider
            title="Speed"
            min={0.1}
            max={2}
            step={0.1}
            value={speed}
            onChange={(val) => setSpeed(val)}
          />
        </Customize>

