              <input
                type="color"
                value={strokeColor}
                width="60px"
                onChange={(e) => {
                  setStrokeColor(e.target.value);
                  forceRerender();
                }}
              />
            </Flex>
          </Flex>

          <Text mt={6} color='#999'>Animation Settings</Text>
          <Flex gap={4} flexWrap="wrap">
            <PreviewSwitch
              title="Flex"
              isChecked={flex}
              onChange={(checked) => {
                setFlex(checked);
                forceRerender();
              }}
            />
            <PreviewSwitch
              title="Alpha"
              isChecked={alpha}
              onChange={(checked) => {
                setAlpha(checked);
                forceRerender();
              }}
            />
            <PreviewSwitch
              title="Stroke"
              isChecked={stroke}
              onChange={(checked) => {
                setStroke(checked);
                forceRerender();
              }}
            />
            <PreviewSwitch
              title="Width"
              isChecked={width}
              onChange={(checked) => {
                setWidth(checked);
                forceRerender();
              }}
            />
            <PreviewSwitch
              title="Weight"
              isChecked={weight}
              onChange={(checked) => {
                setWeight(checked);
                forceRerender();
              }}
            />
            <PreviewSwitch
              title="Italic"
              isChecked={italic}
              onChange={(checked) => {
                setItalic(checked);
                forceRerender();
              }}
            />
          </Flex>
        </Customize>

        <PropTable data={propData} />
      </PreviewTab>

      <CodeTab>
        <CodeExample codeObject={textPressure} />
      </CodeTab>

      <CliTab>
        <CliInstallation {...textPressure} />
      </CliTab>
    </TabbedLayout>
  );
};

export default TextPressureDemo;

